<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {api,errorText} from '../../api/zenflow/client';
interface Post{id:string;title:string;text:string;author:string;category:string;state:string;version:number;featured:boolean;reviewNote?:string;createdAt:string;images:{id:string;thumbnail:string}[]}
const rows=ref<Post[]>([]),state=ref('PENDING'),loading=ref(false),cursor=ref(''),selected=ref<Post>(),note=ref(''),featured=ref(false),busy=ref(false),originalImages=ref<string[]>([]);
const labels:Record<string,string>={PENDING:'待审核',APPROVED:'已公开',REJECTED:'已驳回',WITHDRAWN:'作者已撤回',REMOVED:'已下架',ESSAY:'随笔',SHORT:'短句',POEM:'诗'};
let ticket=0;
async function load(more=false){const request=++ticket;loading.value=true;try{const {data}=await api.get('/community/posts',{params:{state:state.value,...(more?{before:cursor.value}:{})}});if(request!==ticket)return;rows.value=more?[...rows.value,...data.items]:data.items;cursor.value=data.hasMore?data.nextCursor:'';}catch(e){ElMessage.error(errorText(e));}finally{if(request===ticket)loading.value=false;}}
function open(post:Post){selected.value=post;note.value=post.reviewNote||'';featured.value=post.featured;originalImages.value=[];}
async function readImages(){const post=selected.value;if(!post)return;busy.value=true;try{const images=await Promise.all(post.images.map(image=>api.get(`/community/attachments/${image.id}`)));if(selected.value?.id===post.id)originalImages.value=images.map(r=>r.data.uri);}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function review(action:string){const post=selected.value;if(!post||busy.value)return;try{await ElMessageBox.confirm(action==='APPROVE'?'这篇作品及图片将向用户公开。':action==='TAKEDOWN'?'下架后用户无法继续查看作品和图片。':action==='REJECT'?'作品保持非公开，审核意见将告知作者。':'更新此作品的推荐标记。','确认审核操作',{confirmButtonText:'确认',cancelButtonText:'取消'});}catch{return;}busy.value=true;try{await api.post(`/community/posts/${post.id}/review`,{action,expectedVersion:post.version,reviewNote:note.value,featured:featured.value});ElMessage.success('审核状态已更新');selected.value=undefined;await load();}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section><div class="page-heading"><div><div class="eyebrow">SHARED PAGES</div><h1>创作社区</h1><p class="muted">仅管理用户主动投稿的文字和图片；个人记录不会进入审核列表。</p></div><el-button :loading="loading" @click="load()">刷新</el-button></div><el-select v-model="state" @change="load()" style="width:180px"><el-option label="全部状态" value="ALL"/><el-option v-for="key in ['PENDING','APPROVED','REJECTED','WITHDRAWN','REMOVED']" :key="key" :value="key" :label="labels[key]"/></el-select><el-table v-loading="loading" :data="rows" empty-text="暂无作品" style="margin-top:20px"><el-table-column prop="title" label="作品" min-width="220"/><el-table-column prop="author" label="作者" min-width="120"/><el-table-column label="类型" width="85"><template #default="{row}">{{labels[row.category]}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}">{{labels[row.state]}}</template></el-table-column><el-table-column label="推荐" width="70"><template #default="{row}">{{row.featured?'是':'—'}}</template></el-table-column><el-table-column prop="createdAt" label="投稿时间" min-width="170"/><el-table-column width="100"><template #default="{row}"><el-button text @click="open(row)">查看审核</el-button></template></el-table-column></el-table><el-button v-if="cursor" @click="load(true)" :disabled="loading" style="margin-top:16px">更多作品</el-button>
<el-dialog :model-value="!!selected" @close="selected=undefined" title="作品审核" width="min(760px,94vw)"><template v-if="selected"><p class="muted">{{selected.author}} · {{labels[selected.category]}} · {{labels[selected.state]}}</p><h2>{{selected.title}}</h2><div class="paper">{{selected.text}}</div><div class="images"><el-image v-for="(image,index) in selected.images" :key="image.id" :src="originalImages[index]||image.thumbnail" :preview-src-list="originalImages.length?originalImages:selected.images.map(x=>x.thumbnail)" fit="contain" style="width:140px;height:140px"/></div><el-button v-if="selected.images.length&&!originalImages.length" :loading="busy" @click="readImages">查看完整图片</el-button><el-input v-model="note" type="textarea" maxlength="500" show-word-limit placeholder="审核意见（作者可见）" :disabled="!['PENDING','APPROVED'].includes(selected.state)" style="margin-top:16px"/><el-checkbox v-if="['PENDING','APPROVED'].includes(selected.state)" v-model="featured">首页推荐作品</el-checkbox></template><template #footer><el-button @click="selected=undefined">关闭</el-button><template v-if="selected?.state==='PENDING'"><el-button type="danger" :disabled="busy" @click="review('REJECT')">驳回</el-button><el-button type="primary" :disabled="busy" @click="review('APPROVE')">审核并公开</el-button></template><template v-if="selected?.state==='APPROVED'"><el-button type="danger" :disabled="busy" @click="review('TAKEDOWN')">下架</el-button><el-button type="primary" :disabled="busy" @click="review('FEATURE')">更新推荐</el-button></template></template></el-dialog></section></template>
<style scoped>.paper{white-space:pre-wrap;font-family:Georgia,'Songti SC',serif;font-size:18px;line-height:2;background:#faf8ee;padding:24px;border:1px solid #e4e3d5}.images{display:flex;flex-wrap:wrap;gap:12px;margin-top:16px}</style>
